#!/usr/bin/env bash
# Rebuild a merge that conflicts in package.json and package-lock.json.
set -euo pipefail
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
export GIT_AUTHOR_DATE="2026-01-01T12:00:00Z" GIT_COMMITTER_DATE="2026-01-01T12:00:00Z"
git init -q -b main
echo '.agents/' >> .git/info/exclude
echo '.cheese/' >> .git/info/exclude
echo 'restore-repo.sh' >> .git/info/exclude
git config user.email journey@example.invalid
git config user.name Journey
cat > package.json <<'EOF'
{
  "name": "storefront",
  "version": "1.0.0",
  "dependencies": {
    "left-pad": "1.3.0"
  }
}
EOF
cat > package-lock.json <<'EOF'
{
  "name": "storefront",
  "version": "1.0.0",
  "lockfileVersion": 3,
  "packages": {
    "": {
      "name": "storefront",
      "version": "1.0.0",
      "dependencies": {
        "left-pad": "1.3.0"
      }
    },
    "node_modules/left-pad": {
      "version": "1.3.0"
    }
  }
}
EOF
git add -A
git commit -q -m "chore: initial deps"
git checkout -q -b feature/dates
cat > package.json <<'EOF'
{
  "name": "storefront",
  "version": "1.0.0",
  "dependencies": {
    "dayjs": "1.11.10",
    "left-pad": "1.3.0"
  }
}
EOF
cat > package-lock.json <<'EOF'
{
  "name": "storefront",
  "version": "1.0.0",
  "lockfileVersion": 3,
  "packages": {
    "": {
      "name": "storefront",
      "version": "1.0.0",
      "dependencies": {
        "dayjs": "1.11.10",
        "left-pad": "1.3.0"
      }
    },
    "node_modules/dayjs": {
      "version": "1.11.10"
    },
    "node_modules/left-pad": {
      "version": "1.3.0"
    }
  }
}
EOF
git commit -q -am "feat: add dayjs"
git checkout -q main
cat > package.json <<'EOF'
{
  "name": "storefront",
  "version": "1.0.0",
  "dependencies": {
    "left-pad": "1.3.0",
    "zod": "3.22.4"
  }
}
EOF
cat > package-lock.json <<'EOF'
{
  "name": "storefront",
  "version": "1.0.0",
  "lockfileVersion": 3,
  "packages": {
    "": {
      "name": "storefront",
      "version": "1.0.0",
      "dependencies": {
        "left-pad": "1.3.0",
        "zod": "3.22.4"
      }
    },
    "node_modules/left-pad": {
      "version": "1.3.0"
    },
    "node_modules/zod": {
      "version": "3.22.4"
    }
  }
}
EOF
git commit -q -am "feat: add zod"
git merge feature/dates >/dev/null 2>&1 || true
git status --short

#!/usr/bin/env bash
# Rebuild a merge where main renamed a module and both sides edited the same lines.
set -euo pipefail
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
export GIT_AUTHOR_DATE="2026-01-01T12:00:00Z" GIT_COMMITTER_DATE="2026-01-01T12:00:00Z"
git init -q -b main
echo '.agents/' >> .git/info/exclude
echo '.cheese/' >> .git/info/exclude
echo 'restore-repo.sh' >> .git/info/exclude
git config user.email journey@example.invalid
git config user.name Journey
mkdir -p src
cat > src/utils.py <<'EOF'
"""Small string helpers."""


def slugify(text):
    return text.lower().replace(" ", "-")


def shout(text):
    return text.upper()


def whisper(text):
    return text.lower()
EOF
cat > src/app.py <<'EOF'
from src.utils import slugify


def page_url(title):
    return "/p/" + slugify(title)
EOF
touch src/__init__.py
git add -A
git commit -q -m "feat: string helpers"
git checkout -q -b feature/slugs
cat > src/utils.py <<'EOF'
"""Small string helpers."""


def slugify(text):
    return "-".join(text.lower().split())


def shout(text):
    return text.upper()


def whisper(text):
    return text.lower()
EOF
git commit -q -am "fix: slugify collapses repeated spaces"
git checkout -q main
git mv src/utils.py src/helpers.py
sed -i 's/from src.utils import/from src.helpers import/' src/app.py
cat > src/helpers.py <<'EOF'
"""Small string helpers."""


def slugify(text):
    return text.strip().lower().replace(" ", "-")


def shout(text):
    return text.upper()


def whisper(text):
    return text.lower()
EOF
git add -A
git commit -q -m "refactor: rename utils to helpers and strip input"
git merge feature/slugs >/dev/null 2>&1 || true
git status --short

